      }
    ],
    "lacunas": [],
    "motivo": "A linha base fixa é R$ 5.000,00, equivalente a 500.000 centavos.",
    "unidade": "BRL_centavo"
  },
  "custo_novo": {
    "estado": "indeterminado",
    "valor": null,
    "direcao": "desconhecida",
    "evidencias": [
      {
        "fonte_id": "f_41bd418f24",
        "localizador": "L01"
      },
      {
        "fonte_id": "f_e3f0ade479",
        "localizador": "L01"
      },
      {
        "fonte_id": "f_77c5d27cd0",
        "localizador": "L02"
      },
      {
        "fonte_id": "f_e63d1b2e94",
        "localizador": "L02"
      }
    ],
    "lacunas": [
      "O custo de readequação não está definido caso o laudo não seja aceito.",
      "Não se sabe se haverá extensão além de D10, que geraria cobrança por dia."
    ],
    "motivo": "Há cobrança adicional certa pela troca, mas o custo total depende de readequação técnica e de eventual extensão.",
    "unidade": "BRL_centavo"
  },
  "delta_centavos": {
    "estado": "direcao",
    "valor": null,
    "direcao": "aumento",
    "evidencias": [
      {
        "fonte_id": "f_41bd418f24",
        "localizador": "L01"
      },
      {
        "fonte_id": "f_aa2f56bbb7",
        "localizador": "L03"
      },
      {
        "fonte_id": "f_77c5d27cd0",
        "localizador": "L02"
      },
      {
        "fonte_id": "f_e3f0ade479",
        "localizador": "L01"
      }
    ],
    "lacunas": [
      "A magnitude total não é determinável: eventual readequação não tem preço definido e eventual extensão depende do término final."
    ],
    "motivo": "A troca acrescenta R$ 200,00 sem crédito compensatório; custos adicionais possíveis impedem determinar o aumento total.",
    "unidade": "BRL_centavo"
  },
  "justificativa": "O aviso torna certa a cobrança adicional de R$ 200,00, mas não decide o aceite do lote substituto. Sem essa decisão e sem as relações de precedência necessárias, não é possível estimar o término nem quantificar eventual readequação ou extensão."
}

